INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (10, 1, 142, 1, "お礼にいただいたお弁当が、\nあまりにもおいしくて……", 11, 0, 142012, 1, 0, 0);
